# 列表分页：返回第 page_index 页（从 0 开始）的元素列表。
# 页大小固定，最后一页不足时按实际元素返回，越界页返回空列表。


def paginate(items, page_index, page_size):
    """返回第 page_index 页的列表切片。"""
    if page_size <= 0:
        raise ValueError("page_size must be positive")
    if page_index < 0:
        raise ValueError("page_index must be non-negative")

    start = page_index * page_size
    # 错误：把切片末端当成闭区间端点，多取了一个元素。
    end = start + page_size + 1
    return list(items[start:end])

verification_tests:
from target import paginate

ITEMS = ["a", "b", "c", "d", "e"]


def test_first_page():
    assert paginate(ITEMS, 0, 2) == ["a", "b"]


def test_middle_page():
    assert paginate(ITEMS, 1, 2) == ["c", "d"]


def test_out_of_range_page_is_empty():
    assert paginate(ITEMS, 9, 2) == []
